import { apiBase } from "./api";

/**
 * Serves an XML file generated by the blog API (sitemap, RSS) from www.umbreen.com itself,
 * so crawlers find it at the standard location. Cached at the edge for an hour.
 */
export async function proxyXml(path: string, contentType: string): Promise<Response> {
  try {
    const r = await fetch(`${apiBase()}${path}`, { headers: { accept: contentType } });
    if (!r.ok) throw new Error(String(r.status));
    return new Response(await r.text(), {
      headers: { "content-type": `${contentType}; charset=utf-8`, "cache-control": "public, max-age=3600, s-maxage=3600" },
    });
  } catch {
    return new Response("Temporarily unavailable", { status: 503, headers: { "retry-after": "300", "cache-control": "no-store" } });
  }
}
